class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        k = len(s1)
        if k > len(s2):
            return False
        need = [0] * 26
        have = [0] * 26
        for ch in s1:
            need[ord(ch) - 97] += 1
        for i, ch in enumerate(s2):
            have[ord(ch) - 97] += 1
            if i >= k:                            # window too wide: drop s2[i-k]
                have[ord(s2[i - k]) - 97] -= 1
            if have == need:                      # same letter multiset = a permutation
                return True
        return False

