class Solution:
    def minWindow(self, s: str, t: str) -> str:
        need = Counter(t)
        missing = len(t)                     # chars of t still not in the window
        left = 0
        best_start, best_len = 0, float("inf")
        for right, ch in enumerate(s):
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1                    # negative count = surplus copies
            if missing == 0:                 # window covers t: shrink the left edge
                while need[s[left]] < 0:
                    need[s[left]] += 1
                    left += 1
                if right - left + 1 < best_len:
                    best_start, best_len = left, right - left + 1
                need[s[left]] += 1           # evict a required char so right must grow again
                missing += 1
                left += 1
        return "" if best_len == float("inf") else s[best_start:best_start + best_len]

class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        dq = deque()                               # indices; values strictly decreasing
        out = []
        for i, x in enumerate(nums):
            while dq and nums[dq[-1]] <= x:        # x dominates older, smaller values
                dq.pop()
            dq.append(i)
            if dq[0] <= i - k:                     # front slid out of the window
                dq.popleft()
            if i >= k - 1:
                out.append(nums[dq[0]])
        return out

