class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        ops = {
            "+": lambda a, b: a + b,
            "-": lambda a, b: a - b,
            "*": lambda a, b: a * b,
            "/": lambda a, b: int(a / b),          # truncate toward zero, not floor
        }
        stack = []
        for tok in tokens:
            if tok in ops:
                b, a = stack.pop(), stack.pop()    # second-popped is the left operand
                stack.append(ops[tok](a, b))
            else:
                stack.append(int(tok))
        return stack[0]

