class Solution:
    def decodeString(self, s: str) -> str:
        stack = []                              # frames: (text before '[', repeat count)
        cur, num = "", 0
        for ch in s:
            if ch.isdigit():
                num = num * 10 + int(ch)        # counts may have several digits
            elif ch == "[":
                stack.append((cur, num))        # park the outer context
                cur, num = "", 0
            elif ch == "]":
                prev, k = stack.pop()
                cur = prev + cur * k            # resume the outer context
            else:
                cur += ch
        return cur

