class Solution:
    def simplifyPath(self, path: str) -> str:
        stack = []
        for part in path.split("/"):
            if part == "..":
                if stack:
                    stack.pop()                    # go up one level; no-op at root
            elif part and part != ".":
                stack.append(part)                 # "" (from //) and "." are skipped
        return "/" + "/".join(stack)

class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        chars = list(s)
        stack = []                                 # indices of '(' not yet closed
        for i, ch in enumerate(s):
            if ch == "(":
                stack.append(i)
            elif ch == ")":
                if stack:
                    stack.pop()
                else:
                    chars[i] = ""                  # unmatched ')': delete
        for i in stack:                            # '(' never closed: delete
            chars[i] = ""
        return "".join(chars)

